import pandas as pd
from dateutil import parser

def parse_date(val):
    if pd.isna(val):
        return pd.NaT
    s = str(val).strip()
    # Try ISO first
    for fmt in ('%Y-%m-%d', '%Y-%m-%d %H:%M:%S'):
        try:
            dt = pd.to_datetime(s, format=fmt)
            if pd.notna(dt):
                return dt
        except:
            pass
    # Try dayfirst formats
    for fmt in ('%d/%m/%Y', '%d/%m/%y', '%d %b %Y', '%d %B %Y', '%d-%m-%Y'):
        try:
            dt = pd.to_datetime(s, format=fmt)
            if pd.notna(dt):
                return dt
        except:
            pass
    # fallback to dateutil
    try:
        dt = parser.parse(s, dayfirst=True)
        return pd.Timestamp(dt)
    except:
        return pd.NaT

tests = ['2025-04-03','03/04/2025','3 Apr 2025','2025-06-04','2025-08-01','18 Jul 2025']
for t in tests:
    print(t, parse_date(t))

import pandas as pd
import re
from dateutil import parser

file_path = '/data/mixed_units_register.xlsx'
df_raw = pd.read_excel(file_path, sheet_name='Disbursement Register', header=None)
header = df_raw.iloc[5].tolist()
data = df_raw.iloc[6:].copy()
data.columns = header
data = data[data['Record ID'].notna() & (data['Record ID']!='')].copy()

def parse_date(val):
    if pd.isna(val):
        return pd.NaT
    s = str(val).strip()
    # Try specific formats
    for fmt in ('%Y-%m-%d', '%d/%m/%Y', '%d/%m/%y', '%d %b %Y', '%d %B %Y', '%d-%m-%Y'):
        try:
            dt = pd.to_datetime(s, format=fmt)
            if pd.notna(dt):
                return dt
        except:
            pass
    try:
        dt = parser.parse(s, dayfirst=True)
        return pd.Timestamp(dt)
    except:
        return pd.NaT

data['Parsed Date'] = data['Disbursement Date'].apply(parse_date)

def parse_amount(val):
    if pd.isna(val):
        return 0.0
    s = str(val).strip()
    if s == '' or s == '-' or s.upper() == 'NA' or s.upper() == 'NAN':
        return 0.0
    s_clean = s.replace('₹','').replace(',','').strip()
    m = re.match(r'^([0-9]*\.?[0-9]+)\s*([a-zA-Z]+)?$', s_clean)
    if m:
        num_str = m.group(1)
        unit = m.group(2) or ''
        try:
            num = float(num_str)
        except:
            return 0.0
        unit_low = unit.lower()
        if unit_low in ['k']:
            mult = 1000
        elif unit_low in ['l','lakh']:
            mult = 100000
        elif unit_low in ['cr','crore']:
            mult = 10000000
        else:
            mult = 1
        return num * mult
    else:
        try:
            num_only = re.sub(r'[^\d\.]', '', s_clean)
            if num_only:
                return float(num_only)
        except:
            pass
        return 0.0

data['Amount INR'] = data['Amount'].apply(parse_amount)

mask_prog = data['Programme'].astype(str).str.strip() == 'Maternal & Child Health'
mask_date = (data['Parsed Date'] >= pd.Timestamp('2025-04-01')) & (data['Parsed Date'] <= pd.Timestamp('2025-06-30'))
filtered = data[mask_prog & mask_date]
print("Filtered rows count:", len(filtered))
print(filtered[['Record ID','Disbursement Date','Parsed Date','Amount','Amount INR']])
total = filtered['Amount INR'].sum()
print("Total INR:", total)
